// ⭐ 2026-09-11 (Animations-Agent) PRUEF-HAKEN fuer die echte-Verifikation am
// laufenden Fenster (xdotool), weil Chrome ohne Debug-Port laeuft und es
// keinen anderen Weg gibt, eine Sonderausdruck-Sequenz deterministisch zu
// triggern. Keine UX-Funktion: nur Tasten, die niemand drueckt. 'b' loest
// EINEN einzelnen Blink aus (zeitplanNeu=false -- dieselbe Einmal-Kette wie
// der Doppelschlag, kein Extra-Strang), 'k' eine kleine Kopfneigung mit
// Rueckweg OHNE die reguläre Planerkette anzufassen, 'x' einen zufaelligen
// Sonderausdruck aus den drei emote-Pools.
window.addEventListener("keydown", (e) => {
  if(e.key === "b"){ e.preventDefault(); blinzeln(false); }
  else if(e.key === "k"){
    e.preventDefault();
    if(!kopfRollSchritte && !_sonderLaeuft){
      kopfPose = "roll"; kopfRollSoll = 15; gesichtNeuZeichnen();
      kopfRollSequenzZu(15, () => setTimeout(() => {
        kopfRollSequenzZu(0, () => { kopfPose = null; kopfRollSoll = 0; gesichtNeuZeichnen(); });
      }, 1400));
    }
  }
  else if(e.key === "x"){
    e.preventDefault();
    const alle = KATEGORIE_SONDERAUSDRUCK.self_confident;
    const wahl = alle[Math.floor(Math.random()*alle.length)];
    sonderausdruckZeigen(wahl[0], wahl[1]);
  }
});

